  async open() {
    await this.page.getByRole('tab', { name: 'Approvals' }).click();
  }

  getDecisionError() {
    return this.page.getByRole('alert');
  }

  getPendingInvoice(customerName: string) {
    return this.page.getByRole('listitem').filter({ hasText: customerName });
  }

